import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"数据库初始化","description":"","frontmatter":{"title":"数据库初始化","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/03-实战-新蜂商城/数据库初始化.md","filePath":"posts/java快速入门/第九部分：微服务/03-实战-新蜂商城/数据库初始化.md"}'),a={name:"posts/java快速入门/第九部分：微服务/03-实战-新蜂商城/数据库初始化.md"};function s(p,e,_,r,n,i){return c(),d("div",null,[...e[0]||(e[0]=[t("<div><p>一、从<code>gitlee</code>上下载源文件；</p><p>二、打开<code>navicat</code>管理软件，新建一个连接：</p><p>三、打开连接：</p><p>四、新建一个数据库，命名为 <code>newbee_mall_db_v2</code>，当然，也可以是其它名称。</p><p>字符集 在中国地区一般使用的编码方式大部分都是<code>UTF-8</code>，但是<code>Mysql</code>的数据库中给出了两种选“<code>utf8</code>”<code>,</code>一个是“<code>utf8mb4</code>”。根据查询资料得知<code>Mysql</code>的“<code>utf8</code>”并不是我们常见到的<code>UTF-8</code>，反而“<code>utf8mb4</code>”是我们常用的<code>UTF-8</code>。为什么会这样呢？</p><p><code>Mysql</code>中的“<code>utf8</code>”编码只支持每个字符最大<code>3</code>个字节的编码方式，而我们通常使用的<code>UTF-8</code>是每个字符最大<code>4</code>个字节的编码方式。所以在我们这边，尤其是存储汉字的时候，需要使用的编码方式是“<code>utf8mb4</code>”。</p><p>排序规则 <code>utf8_general_ci</code> 不区分大小写，这个你在注册用户名和邮箱的时候就要使用。 <code>utf8_general_cs</code> 区分大小写，如果用户名和邮箱用这个 就会照成不良后果 <code>utf8_bin:</code>字符串每个字符串用二进制数据编译存储。 区分大小写，而且可以存二进制的内容 <code>utf8_unicode_ci</code>和<code>utf8_general_ci</code>对中、英文来说没有实质的差别。 <code>utf8_general_ci</code>校对速度快，但准确度稍差。（准确度够用，一般建库选择这个） <code>utf8_unicode_ci</code>准确度高，但校对速度稍慢。 因此，我们在建库时一般选择<code>utf8mb4 utf8mb4_general_ci</code>的方式</p><p>五、在数据库中新建查询，由于不能运行<code>sql</code>文件，只能复制源码中的<code>sql</code>查询到这里运行：</p><p>六、运行完毕，打开数据库，可以看到生成的数据表：</p><p><strong>七、修改数据库连接配置</strong> 导入成功后，打开 <code>application.properties</code> 配置文件，修改数据库连接的相关信息，默认的数据库配置如下：</p><p>spring.datasource.url=jdbc:mysql://localhost:3306/newbee_mall_db_v2?useUnicode=true&amp;serverTimezone=Asia/Shanghai&amp;characterEncoding=utf8&amp;autoReconnect=true&amp;useSSL=false&amp;allowMultiQueries=true spring.datasource.username=root spring.datasource.password=123456 八、重新跑一下，看有没有报错；</p></div>",1)])])}const f=o(a,[["render",s]]);export{u as __pageData,f as default};
